-- Forward upgrade of the saved 0.5 development checkpoint. No data reset.
begin;
alter table if exists public.cp_batches add column if not exists committed_at timestamptz;
alter table if exists public.cp_photo_intents drop constraint if exists cp_photo_intents_path_key;
create table if not exists public.cp_workspace(company uuid primary key references public.cp_companies(id),local_company uuid not null);
create table if not exists public.cp_packets(company uuid not null references public.cp_companies(id),kind text not null,id uuid not null,site uuid,local_company uuid not null,data jsonb not null,revision bigint not null,sequence bigint not null,primary key(company,kind,id));
create table if not exists public.cp_batches(company uuid not null,user_id uuid not null,id uuid not null,request jsonb not null,receipt jsonb,committed_at timestamptz,created_at timestamptz not null default now(),primary key(company,id));
create table if not exists public.cp_source_receipts(company uuid not null,kind text not null,id uuid not null,payload jsonb not null,batch_id uuid not null,primary key(company,kind,id));
create table if not exists public.cp_photo_intents(id uuid primary key default gen_random_uuid(),company uuid not null,batch_id uuid not null,asset_id uuid not null,inspection uuid not null,site uuid not null,hash text not null check(hash~'^[a-f0-9]{64}$'),bytes integer not null check(bytes between 1 and 1000000),path text not null,ready boolean not null default false,created_at timestamptz not null default now(),unique(company,batch_id,asset_id),foreign key(company,batch_id) references public.cp_batches(company,id));
alter table public.cp_workspace enable row level security;alter table public.cp_packets enable row level security;alter table public.cp_batches enable row level security;alter table public.cp_source_receipts enable row level security;alter table public.cp_photo_intents enable row level security;
revoke all on public.cp_workspace,public.cp_packets,public.cp_batches,public.cp_source_receipts,public.cp_photo_intents from anon,authenticated;
create or replace function public.cp_sync_access(c uuid,k text,i uuid,s uuid) returns boolean language sql stable security definer set search_path='' as $$select coalesce(public.cp_role(c)='owner' or (public.cp_role(c)='inspector' and (k in ('template','person','branding') or public.cp_site_access(c,s) or (k='customer' and exists(select 1 from public.cp_packets p join public.cp_assignments a on a.company_id=p.company and a.site_id=p.id and a.user_id=auth.uid() where p.company=c and p.kind='site' and p.data->'sites'->0->>'customer_id'=i::text)))),false)$$;
do $$begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='cp_packets' and policyname='packets_read') then create policy packets_read on public.cp_packets for select to authenticated using(public.cp_sync_access(company,kind,id,site));end if;end$$;grant select on public.cp_packets to authenticated;
create or replace function public.cp_sync_register(c uuid,lc uuid) returns uuid language plpgsql security definer set search_path='' as $$declare prior uuid;begin perform 1 from public.cp_companies where id=c for update;if public.cp_role(c) is null then raise exception 'Company access denied' using errcode='42501';end if;select local_company into prior from public.cp_workspace where company=c;if prior is not null then if prior<>lc then raise exception 'Different workspace identity; explicit mapping review required';end if;return prior;end if;if public.cp_role(c)<>'owner' then raise exception 'Owner adoption required' using errcode='42501';end if;insert into public.cp_workspace values(c,lc);return lc;end$$;
create or replace function public.cp_sync_candidate(c uuid,k text,i text,records jsonb) returns jsonb language sql stable security definer set search_path='' as $$select coalesce((select r->'data' from jsonb_array_elements(records)r where r->>'kind'=k and r->>'id'=i limit 1),(select data from public.cp_packets where company=c and kind=k and id::text=i))$$;
create or replace function public.cp_sync_validate(c uuid,lc uuid,r jsonb,records jsonb) returns void language plpgsql security definer set search_path='' as $$declare k text:=r->>'kind';rid text:=r->>'id';p jsonb:=r->'data';old jsonb;t record;a jsonb;b jsonb;d jsonb;w jsonb;l jsonb;item jsonb;names text[];table_name text;begin
 names:=case k when 'customer' then array['customers'] when 'site' then array['sites'] when 'person' then array['local_people'] when 'branding' then array['company_settings'] when 'template' then array['templates','template_versions'] when 'inspection' then array['inspection_drafts','inspection_context','inspection_lifecycle','corrective_actions','action_history','media_journal'] else null end;
 if names is null or jsonb_typeof(p) is distinct from 'object' or (r->>'id')::uuid is null or (r->>'revision')::bigint is null or (r->>'revision')::bigint<0 or (select count(*) from jsonb_object_keys(p))<>cardinality(names) then raise exception 'Invalid record';end if;
 foreach table_name in array names loop if jsonb_typeof(p->table_name) is distinct from 'array' then raise exception 'Invalid table set';end if;for a in select * from jsonb_array_elements(p->table_name)loop if a->>'company_id' is distinct from lc::text then raise exception 'Invalid company mapping';end if;end loop;end loop;
 if k not in ('site','inspection') and r->>'siteId' is not null then raise exception 'Invalid catalogue scope';end if;
 if exists(select 1 from public.cp_packets p where p.company=c and p.kind=k and p.id::text=rid and p.site is distinct from (r->>'siteId')::uuid) then raise exception 'Record site scope is immutable' using errcode='42501';end if;
 if k<>'inspection' and (jsonb_array_length(p->names[1])<>1 or coalesce(p->names[1]->0->>'id',p->names[1]->0->>'company_id') is distinct from rid) then raise exception 'Identity mismatch';end if;
 if k in ('customer','site','template','person','branding') and (jsonb_typeof(p->names[1]->0->'name') is distinct from 'string' or length(trim(p->names[1]->0->>'name')) not between 1 and 120) then raise exception 'Name required';end if;
 if k='site' and (r->>'siteId' is distinct from rid or public.cp_sync_candidate(c,'customer',p->'sites'->0->>'customer_id',records) is null) then raise exception 'Invalid site dependency';end if;
 if k='template' then if (select count(*) from jsonb_array_elements(p->'template_versions'))<>(select count(distinct x->>'id') from jsonb_array_elements(p->'template_versions')x) or (select count(*) from jsonb_array_elements(p->'template_versions'))<>(select count(distinct x->>'version') from jsonb_array_elements(p->'template_versions')x) then raise exception 'Duplicate template version';end if;for a in select * from jsonb_array_elements(p->'template_versions')loop if a->>'template_id' is distinct from rid or jsonb_typeof((a->>'items_json')::jsonb) is distinct from 'array' or jsonb_array_length((a->>'items_json')::jsonb) not between 1 and 50 then raise exception 'Invalid template';end if;end loop;end if;
 if k='inspection' then
  if jsonb_array_length(p->'inspection_drafts')<>1 or jsonb_array_length(p->'inspection_context')<>1 or jsonb_array_length(p->'inspection_lifecycle')>1 then raise exception 'Invalid inspection rows';end if;
  d:=(p->'inspection_drafts'->0->>'payload_json')::jsonb;w:=(p->'inspection_context'->0->>'workspace_json')::jsonb;l:=p->'inspection_lifecycle'->0;
  if p->'inspection_drafts'->0->>'id' is distinct from rid or p->'inspection_context'->0->>'inspection_id' is distinct from rid or p->'inspection_drafts'->0->>'site_id' is distinct from r->>'siteId' or d->>'id' is distinct from rid or w->>'inspectionId' is distinct from rid or d->>'companyId' is distinct from lc::text or w->>'companyId' is distinct from lc::text or d->>'siteId' is distinct from r->>'siteId' or w->>'siteId' is distinct from r->>'siteId' or public.cp_sync_candidate(c,'site',r->>'siteId',records) is null then raise exception 'Inspection scope mismatch';end if;
  if not exists(select 1 from (select data from public.cp_packets where company=c and kind='template' union all select x->'data' from jsonb_array_elements(records)x where x->>'kind'='template') q,jsonb_array_elements(q.data->'template_versions')v where v->>'id'=w->>'templateVersionId') then raise exception 'Template dependency missing';end if;
  if jsonb_typeof(w->'items') is distinct from 'array' or jsonb_typeof(d->'responses') is distinct from 'object' or jsonb_array_length(w->'items') not between 1 and 50 or (select count(*) from jsonb_object_keys(d->'responses'))<>jsonb_array_length(w->'items') then raise exception 'Invalid checklist';end if;
  for item in select * from jsonb_array_elements(w->'items')loop a:=d->'responses'->(item->>'id');if a is null or (a->>'result' is not null and a->>'result' not in ('pass','fail','na')) or jsonb_typeof(a->'note') is distinct from 'string' or length(a->>'note')>2000 then raise exception 'Invalid response';end if;
   if l->>'status'='completed' and (a->>'result' is null or (a->>'result' in ('fail','na') and length(trim(a->>'note'))=0)) then raise exception 'Incomplete inspection';end if;
   if l->>'status'='completed' and a->>'result'='fail' and not exists(select 1 from jsonb_array_elements(p->'corrective_actions') x where x->>'item_id'=item->>'id') then raise exception 'Failure action missing';end if;
  end loop;
  if l is not null and (l->>'inspection_id' is distinct from rid or l->>'status' not in ('draft','completed')) then raise exception 'Lifecycle mismatch';end if;
  if l->>'status'='completed' and (((l->>'snapshot_json')::jsonb)->'draft' is distinct from d or ((l->>'snapshot_json')::jsonb)->'context'->'workspace' is distinct from w or length(trim(coalesce(l->>'inspector','')))=0 or l->>'completed_at' is null) then raise exception 'Snapshot mismatch';end if;
  for a in select * from jsonb_array_elements(p->'corrective_actions')loop if a->>'inspection_id' is distinct from rid or a->>'status' not in ('open','resolved') or length(trim(coalesce(a->>'description','')))=0 or a->>'due_date' !~ '^\d{4}-\d{2}-\d{2}$' or public.cp_sync_candidate(c,'person',a->>'owner_id',records) is null or not exists(select 1 from jsonb_array_elements(w->'items')x where x->>'id'=a->>'item_id') or (a->>'status'='resolved' and length(trim(coalesce(a->>'resolution_note','')))=0) then raise exception 'Invalid action';end if;end loop;
  for a in select * from jsonb_array_elements(p->'action_history')loop if not exists(select 1 from jsonb_array_elements(p->'corrective_actions')x where x->>'id'=a->>'action_id') then raise exception 'Invalid history parent';end if;end loop;
  if l->>'status'='completed' then for a in select * from jsonb_array_elements((l->>'snapshot_json')::jsonb->'photos')loop if not exists(select 1 from jsonb_array_elements(p->'media_journal')x where x->>'id'=a->>'id' and x->>'hash'=a->>'hash' and x->>'state'='ready' and x->>'action_id' is null) then raise exception 'Frozen photo missing';end if;end loop;end if;
  if (select count(*) from jsonb_array_elements(p->'media_journal')x where x->>'state'<>'deleted')>20 then raise exception 'Photo limit exceeded';end if;
  for a in select * from jsonb_array_elements(p->'media_journal')loop if exists(select 1 from public.cp_packets q,jsonb_array_elements(q.data->'media_journal')x where q.company=c and q.kind='inspection' and q.id::text<>rid and x->>'id'=a->>'id') or exists(select 1 from jsonb_array_elements(records)q,jsonb_array_elements(q->'data'->'media_journal')x where q->>'kind'='inspection' and q->>'id'<>rid and x->>'id'=a->>'id') then raise exception 'Photo identity already belongs to an inspection';end if;end loop;
  for a in select * from jsonb_array_elements(p->'media_journal')loop if a->>'inspection_id' is distinct from rid or a->>'kind' is distinct from 'photo' or a->>'state' not in ('ready','deleted') or coalesce((a->>'bytes')::integer,0) not between 1 and 1000000 or a->>'hash' !~ '^[a-f0-9]{64}$' or not exists(select 1 from jsonb_array_elements(w->'items')x where x->>'id'=a->>'item_id') or (a->>'action_id' is not null and not exists(select 1 from jsonb_array_elements(p->'corrective_actions')x where x->>'id'=a->>'action_id' and x->>'item_id'=a->>'item_id')) then raise exception 'Invalid photo';end if;end loop;
 end if;
 select data into old from public.cp_packets where company=c and kind=k and id::text=rid and revision=(r->>'revision')::bigint;
 if old is not null then
  if k='inspection' and old->'inspection_lifecycle'->0->>'status'='completed' and (old->'inspection_drafts'<>p->'inspection_drafts' or old->'inspection_context'<>p->'inspection_context' or old->'inspection_lifecycle'<>p->'inspection_lifecycle') then raise exception 'Completed history is immutable';end if;
  foreach table_name in array array['template_versions','action_history']loop for a in select * from jsonb_array_elements(old->table_name)loop if not coalesce(p->table_name @> jsonb_build_array(a),false) then raise exception 'History cannot disappear';end if;end loop;end loop;
  for a in select * from jsonb_array_elements(old->'media_journal')loop select x into b from jsonb_array_elements(p->'media_journal')x where x->>'id'=a->>'id';if b is null or b-'state'<>a-'state' or (a->>'state'='deleted' and b->>'state'<>'deleted') then raise exception 'Evidence identity changed';end if;
   if b->>'state'='deleted' and a->>'state'<>'deleted' and ((old->'inspection_lifecycle'->0->>'status'='completed' and a->>'action_id' is null) or exists(select 1 from jsonb_array_elements(old->'action_history')h,jsonb_array_elements((h->>'snapshot_json')::jsonb->'evidence')ev where h->>'event'='resolved' and ev->>'id'=a->>'id')) then raise exception 'Historical evidence must remain';end if;
  end loop;
 end if;
end$$;
create or replace function public.cp_sync_stage(batch jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare c uuid:=(batch->>'company')::uuid;op uuid:=(batch->>'id')::uuid;lc uuid:=(batch->>'localCompany')::uuid;prior public.cp_batches;r jsonb;begin
 perform 1 from public.cp_companies where id=c for update;if auth.uid() is null or public.cp_role(c) is null then raise exception 'Access denied' using errcode='42501';end if;
 if batch->>'protocol' is distinct from '2' or pg_column_size(batch)>10000000 or jsonb_typeof(batch->'records') is distinct from 'array' or jsonb_array_length(batch->'records')>1000 or jsonb_typeof(batch->'sources') is distinct from 'array' or not exists(select 1 from public.cp_workspace where company=c and local_company=lc) then raise exception 'Invalid batch/mapping';end if;
 select * into prior from public.cp_batches where company=c and id=op;if found then if prior.user_id<>auth.uid() or prior.request<>batch then raise exception 'Operation ID reused';end if;return coalesce(prior.receipt,jsonb_build_object('status','staged'));end if;
 if (select count(*) from jsonb_array_elements(batch->'records'))<>(select count(distinct(x->>'kind',x->>'id')) from jsonb_array_elements(batch->'records')x) then raise exception 'Duplicate records';end if;
 for r in select * from jsonb_array_elements(batch->'records')loop if public.cp_role(c)<>'owner' and (r->>'kind'<>'inspection' or not coalesce(public.cp_site_access(c,(r->>'siteId')::uuid),false)) then raise exception 'Role/site denied' using errcode='42501';end if;perform public.cp_sync_validate(c,lc,r,batch->'records');end loop;
 for r in select * from jsonb_array_elements(batch->'sources')loop if r->>'kind' not in ('outbox','event') or (r->>'kind'='outbox' and r->'row'->>'operation_id' is distinct from r->>'id') or (r->>'kind'='event' and r->'row'->>'id' is distinct from r->>'id') or r->'row'->>'company_id' is distinct from lc::text or (r->>'id')::uuid is null then raise exception 'Invalid original operation';end if;end loop;
 insert into public.cp_batches(company,user_id,id,request)values(c,auth.uid(),op,batch);return jsonb_build_object('status','staged');end$$;
create or replace function public.cp_photo_intent(c uuid,batch uuid,asset uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare req public.cp_batches;r jsonb;a jsonb;result public.cp_photo_intents;begin select * into req from public.cp_batches where company=c and id=batch;if req.user_id is distinct from auth.uid() or public.cp_role(c) is null then raise exception 'Access denied' using errcode='42501';end if;
 for r in select * from jsonb_array_elements(req.request->'records')loop select x into a from jsonb_array_elements(r->'data'->'media_journal')x where x->>'id'=asset::text and x->>'state'='ready';if a is not null then exit;end if;end loop;
 if a is null or not coalesce(public.cp_site_access(c,(r->>'siteId')::uuid),false) then raise exception 'Photo scope denied' using errcode='42501';end if;
 insert into public.cp_photo_intents(company,batch_id,asset_id,inspection,site,hash,bytes,path,ready)values(c,batch,asset,(r->>'id')::uuid,(r->>'siteId')::uuid,a->>'hash',(a->>'bytes')::integer,coalesce((select path from public.cp_photo_intents where company=c and asset_id=asset and hash=a->>'hash' and bytes=(a->>'bytes')::integer and ready limit 1),c::text||'/'||gen_random_uuid()::text||'.jpg'),exists(select 1 from public.cp_photo_intents where company=c and asset_id=asset and hash=a->>'hash' and bytes=(a->>'bytes')::integer and ready))on conflict(company,batch_id,asset_id)do nothing;select * into result from public.cp_photo_intents where company=c and batch_id=batch and asset_id=asset;return to_jsonb(result);end$$;
create or replace function public.cp_photo_check(intent uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.cp_photo_intents;begin select * into r from public.cp_photo_intents where id=intent;if r.id is null or not coalesce(public.cp_site_access(r.company,r.site),false) or not exists(select 1 from public.cp_batches where company=r.company and id=r.batch_id and user_id=auth.uid()) then raise exception 'Access denied' using errcode='42501';end if;return to_jsonb(r);end$$;
create or replace function public.cp_photo_finish(intent uuid,verified_hash text,verified_bytes integer) returns void language plpgsql security definer set search_path='' as $$begin update public.cp_photo_intents set ready=true where id=intent and hash=verified_hash and bytes=verified_bytes;if not found then raise exception 'Integrity mismatch';end if;end$$;
create or replace function public.cp_sync_commit(c uuid,batch uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare saved public.cp_batches;r jsonb;old public.cp_packets;outcome jsonb:='[]';result jsonb;seq bigint;conflict boolean:=false;a jsonb;begin
 perform 1 from public.cp_companies where id=c for update;select * into saved from public.cp_batches where company=c and id=batch;if saved.user_id is distinct from auth.uid() or public.cp_role(c) is null then raise exception 'Access denied' using errcode='42501';end if;if saved.receipt is not null then return saved.receipt;end if;
 for r in select * from jsonb_array_elements(saved.request->'records')loop if public.cp_role(c)<>'owner' and (r->>'kind'<>'inspection' or not coalesce(public.cp_site_access(c,(r->>'siteId')::uuid),false)) then raise exception 'Site/role revoked' using errcode='42501';end if;select * into old from public.cp_packets where company=c and kind=r->>'kind' and id=(r->>'id')::uuid;if coalesce(old.revision,0)<>(r->>'revision')::bigint then conflict:=true;end if;if old.id is not null then outcome:=outcome||jsonb_build_array(jsonb_build_object('kind',old.kind,'id',old.id,'siteId',old.site,'data',old.data,'revision',old.revision));end if;end loop;
 if not conflict then outcome:='[]';for r in select * from jsonb_array_elements(saved.request->'records')loop perform public.cp_sync_validate(c,(saved.request->>'localCompany')::uuid,r,saved.request->'records');for a in select * from jsonb_array_elements(r->'data'->'media_journal')loop if a->>'state'='ready' and not exists(select 1 from public.cp_photo_intents where company=c and batch_id=batch and asset_id=(a->>'id')::uuid and hash=a->>'hash' and ready) then raise exception 'Required photo not verified';end if;end loop;
 update public.cp_companies set cursor=cursor+1 where id=c returning cursor into seq;insert into public.cp_packets values(c,r->>'kind',(r->>'id')::uuid,(r->>'siteId')::uuid,(saved.request->>'localCompany')::uuid,r->'data',(r->>'revision')::bigint+1,seq)on conflict(company,kind,id)do update set data=excluded.data,revision=excluded.revision,sequence=excluded.sequence;outcome:=outcome||jsonb_build_array(r||jsonb_build_object('revision',(r->>'revision')::bigint+1));end loop;
 for r in select * from jsonb_array_elements(saved.request->'sources')loop if exists(select 1 from public.cp_source_receipts where company=c and kind=r->>'kind' and id=(r->>'id')::uuid and payload<>r->'row') then raise exception 'Original source ID reused';end if;insert into public.cp_source_receipts values(c,r->>'kind',(r->>'id')::uuid,r->'row',batch)on conflict do nothing;end loop;end if;
 result:=jsonb_build_object('id',batch,'status',case when conflict then 'conflict' else 'accepted' end,'records',outcome);update public.cp_batches set receipt=result,committed_at=now() where company=c and id=batch;return result;end$$;
-- Scope generations are per member, so adding another colleague does not lock an unchanged owner.
create table if not exists public.cp_member_sync_epochs(company uuid not null,user_id uuid not null,epoch bigint not null,primary key(company,user_id));
alter table public.cp_member_sync_epochs enable row level security;
revoke all on public.cp_member_sync_epochs from anon,authenticated;
insert into public.cp_member_sync_epochs select m.company_id,m.user_id,c.access_epoch from public.cp_memberships m join public.cp_companies c on c.id=m.company_id on conflict do nothing;
create or replace function public.cp_member_sync_epoch_changed() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.cp_member_sync_epochs values(coalesce(new.company_id,old.company_id),coalesce(new.user_id,old.user_id),1) on conflict(company,user_id)do update set epoch=public.cp_member_sync_epochs.epoch+1;return coalesce(new,old);end$$;
drop trigger if exists cp_sync_epoch_members on public.cp_memberships;
create trigger cp_sync_epoch_members after insert or update or delete on public.cp_memberships for each row execute function public.cp_member_sync_epoch_changed();
drop trigger if exists cp_sync_epoch_assignments on public.cp_assignments;
create trigger cp_sync_epoch_assignments after insert or update or delete on public.cp_assignments for each row execute function public.cp_member_sync_epoch_changed();
revoke all on function public.cp_member_sync_epoch_changed() from public;
create or replace function public.cp_sync_pull(c uuid,after_cursor bigint,known_epoch bigint) returns jsonb language plpgsql security definer set search_path='' as $$declare epoch bigint;head bigint;rows jsonb;last_seq bigint;n bigint;begin perform 1 from public.cp_companies where id=c for share;if public.cp_role(c) is null then raise exception 'Access denied' using errcode='42501';end if;select cursor into head from public.cp_companies where id=c;select m.epoch into epoch from public.cp_member_sync_epochs m where m.company=c and m.user_id=auth.uid();if after_cursor<0 or after_cursor>head then raise exception 'Invalid cursor';end if;if known_epoch is not null and known_epoch<>epoch then return jsonb_build_object('scopeChanged',true,'epoch',epoch);end if;
select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'siteId',site,'data',data,'revision',revision) order by sequence),'[]'),max(sequence),count(*) into rows,last_seq,n from (select * from public.cp_packets where company=c and sequence>after_cursor and public.cp_sync_access(c,kind,id,site) order by sequence limit 50)page;
return jsonb_build_object('protocol',2,'scopeChanged',false,'records',rows,'cursor',case when n<50 then head else last_seq end,'head',head,'epoch',epoch);end$$;
create or replace function public.cp_photo_download(c uuid,asset uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.cp_photo_intents;begin select m.* into r from public.cp_photo_intents m left join public.cp_packets p on p.company=m.company and p.id=m.inspection and p.kind='inspection' where m.company=c and m.asset_id=asset and m.ready and (exists(select 1 from jsonb_array_elements(p.data->'media_journal')a where a->>'id'=asset::text and a->>'hash'=m.hash and a->>'state'='ready') or exists(select 1 from public.cp_batches b where b.company=m.company and b.id=m.batch_id and b.user_id=auth.uid() and b.receipt is null))order by m.created_at desc limit 1;if r.id is null or not coalesce(public.cp_site_access(c,r.site),false) then raise exception 'Access denied' using errcode='42501';end if;return to_jsonb(r);end$$;
revoke all on function public.cp_sync_access(uuid,text,uuid,uuid),public.cp_sync_register(uuid,uuid),public.cp_sync_candidate(uuid,text,text,jsonb),public.cp_sync_validate(uuid,uuid,jsonb,jsonb),public.cp_sync_stage(jsonb),public.cp_photo_intent(uuid,uuid,uuid),public.cp_photo_check(uuid),public.cp_photo_finish(uuid,text,integer),public.cp_sync_commit(uuid,uuid),public.cp_sync_pull(uuid,bigint,bigint),public.cp_photo_download(uuid,uuid) from public;
grant execute on function public.cp_sync_access(uuid,text,uuid,uuid),public.cp_sync_register(uuid,uuid),public.cp_sync_stage(jsonb),public.cp_photo_intent(uuid,uuid,uuid),public.cp_photo_check(uuid),public.cp_sync_commit(uuid,uuid),public.cp_sync_pull(uuid,bigint,bigint),public.cp_photo_download(uuid,uuid) to authenticated;
grant execute on function public.cp_photo_finish(uuid,text,integer) to service_role;
commit;
